-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_encounter_location.sql. Do not edit.
-- Silver encounter location: one row per Encounter.location entry, so a visit can be followed from unit to unit
-- and bed to bed. A transfer completes the entries of the old place and adds entries for the new one.
-- An entry with only a display text (no Location reference) keeps location_id NULL.
CREATE OR REPLACE TABLE silver_encounter_location AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Encounter'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
)
SELECT
    l.resource_id                                                                    AS encounter_id,
    loc.index                                                      AS entry_index,
    REPLACE(loc.value:location.reference::string, 'Location/', '')              AS location_id,
    loc.value:location.display::string                                          AS location_display,
    loc.value:status::string                                                    AS status,
    loc.value:physicalType.coding[0].code::string                               AS physical_type,
    TRY_CAST(SUBSTR(loc.value:period.start::string, 1, 19) AS TIMESTAMP_NTZ)                                            AS start_at,
    TRY_CAST(SUBSTR(loc.value:period.end::string, 1, 19) AS TIMESTAMP_NTZ)                                              AS end_at
FROM latest l , LATERAL FLATTEN(input => l.raw:location) loc;
